class MinHeap {
  constructor(compare = (a, b) => a - b) {
    this.items = []
    this.compare = compare
  }
  get size() { return this.items.length }
  peek() { return this.items[0] }
  push(value) {
    const a = this.items
    a.push(value)
    let i = a.length - 1
    while (i > 0) {
      const p = (i - 1) >> 1                     // parent index
      if (this.compare(a[i], a[p]) >= 0) break   // parent is not bigger: done
      ;[a[i], a[p]] = [a[p], a[i]]
      i = p
    }
  }
  pop() {
    const a = this.items
    const top = a[0]
    const last = a.pop()
    if (a.length > 0) {
      a[0] = last
      let i = 0
      while (true) {
        const l = 2 * i + 1
        const r = l + 1
        let best = i
        if (l < a.length && this.compare(a[l], a[best]) < 0) best = l
        if (r < a.length && this.compare(a[r], a[best]) < 0) best = r
        if (best === i) break
        ;[a[i], a[best]] = [a[best], a[i]]
        i = best
      }
    }
    return top
  }
}

