import heapq

def kth_largest(nums, k):
    heap = []                          # min-heap of the k largest so far
    for x in nums:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heapreplace(heap, x)   # pop the root, push x
    return heap[0]

def merge_k_sorted(arrays):
    heap = [(arr[0], i, 0) for i, arr in enumerate(arrays) if arr]
    heapq.heapify(heap)
    out = []
    while heap:
        val, i, j = heapq.heappop(heap)
        out.append(val)
        if j + 1 < len(arrays[i]):
            heapq.heappush(heap, (arrays[i][j + 1], i, j + 1))
    return out

print(kth_largest([3, 2, 1, 5, 6, 4], 2))           # 5
print(merge_k_sorted([[1, 4, 7], [2, 5], [0, 6, 9]]))
# [0, 1, 2, 4, 5, 6, 7, 9]

